node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Current reservation data
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C4C633'\").get();
const flights = JSON.parse(booking.flights_json);
const paymentHistory = JSON.parse(booking.payment_history_json);

console.log('=== BEFORE ===');
console.log('Flights:', JSON.stringify(flights, null, 2));
console.log('Payment history:', JSON.stringify(paymentHistory, null, 2));

// Update the return flight date from 2026-10-05 to 2026-10-01
// The flight FLE7F420 (outbound) stays the same
// The flight FL84B16B (return) changes date to 2026-10-01
const newFlights = flights.map(f => {
    if (f.flight_number === 'FL84B16B') {
        return { ...f, date: '2026-10-01' };
    }
    return f;
});

// Fare difference is \$0 (same price on both dates), so no new payment entry needed

const newFlightsJson = JSON.stringify(newFlights);

// Update the reservation
db.prepare(\"UPDATE flight_bookings SET flights_json = ? WHERE booking_id = 'C4C633'\").run(newFlightsJson);

// Verify
const updated = db.prepare(\"SELECT flights_json, payment_history_json FROM flight_bookings WHERE booking_id = 'C4C633'\").get();
console.log('\n=== AFTER ===');
console.log('Flights:', JSON.stringify(JSON.parse(updated.flights_json), null, 2));
console.log('Payment history:', JSON.stringify(JSON.parse(updated.payment_history_json), null, 2));
"

